        body='\n'.join(lines[i:j])
        names={nm} if isroot else {'.'.join(cur[k:]+[nm]) if cur else nm for k in range(len(cur)+1)}
        for n in names: declmap.setdefault(n,(f,i+1,bool(re.search(r'(?<![\w.])sorry(?![\w])',body))))
envs=('theorem','lemma','proposition','corollary','definition','remark','example','notation','convention')
for fn in files:
    lines=open(os.path.join(chdir,fn),encoding='utf-8').read().split('\n')
    i=0;out=[]
    while i<len(lines):
        l=lines[i]
        m=re.search(r'\\begin\{('+'|'.join(envs)+r')\}',l) if not l.lstrip().startswith('%') else None
        if m:
            j=i;blk=[]
